using Test

function collatz_steps(n::Integer)
    n >= 1 || throw(ArgumentError("n must be positive, got $n"))
    steps = 0
    while n != 1
        n = iseven(n) ? n ÷ 2 : 3n + 1
        steps += 1
    end
    return steps
end

@testset "collatz_steps" begin
    @test iszero(collatz_steps(1))
    @test collatz_steps(6) == 8
    @test collatz_steps(27) == 111
    @test_throws ArgumentError collatz_steps(0)
end
