using Test

function days_in_month(year::Integer, month::Integer)
    1 <= month <= 12 || throw(ArgumentError("month must be in 1:12, got $month"))
    if month == 2
        leap = iszero(year % 4) && (!iszero(year % 100) || iszero(year % 400))
        return leap ? 29 : 28
    end
    return month in (4, 6, 9, 11) ? 30 : 31
end

@testset "days_in_month" begin
    @test days_in_month(2023, 2) == 28
    @test days_in_month(2024, 2) == 29
    @test days_in_month(1900, 2) == 28
    @test_throws ArgumentError days_in_month(2024, 13)
end
