using Test

function median_of(v)
    isempty(v) && throw(ArgumentError("median of an empty collection"))
    s = sort(v)
    n = length(s)
    mid = firstindex(s) + n ÷ 2
    return isodd(n) ? s[mid] : (s[mid-1] + s[mid]) / 2
end

@testset "median_of" begin
    @test median_of([3, 1, 2]) == 2
    @test median_of([4, 1, 3, 2]) === 2.5
    @test median_of([5.0]) == 5.0
    @test_throws ArgumentError median_of(Int[])
end
