using Test

function count_words(s::AbstractString)
    counts = Dict{String,Int}()
    for m in eachmatch(r"\p{L}+", s)
        w = lowercase(m.match)
        counts[w] = get(counts, w, 0) + 1
    end
    return counts
end

@testset "count_words" begin
    @test count_words("The cat and the hat") == Dict("the" => 2, "cat" => 1, "and" => 1, "hat" => 1)
    @test count_words("Ñandú, ñandú!") == Dict("ñandú" => 2)
    @test count_words("123 ... ???") == Dict{String,Int}()
    @test isempty(count_words(""))
end
