using Test

function hamming(a::AbstractString, b::AbstractString)
    length(a) == length(b) ||
        throw(DimensionMismatch("strings have different lengths: $(length(a)) vs $(length(b))"))
    return count(splat(!=), zip(a, b))
end

@testset "hamming" begin
    @test hamming("karolin", "kathrin") == 3
    @test hamming("café", "cafe") == 1
    @test iszero(hamming("", ""))
    @test_throws DimensionMismatch hamming("ab", "abc")
end
